#include <stdio.h>
#include <stdint.h>

#include"stm32c031xx.h"
#include"core_cm0plus.h"

volatile uint32_t ms_counter=0;
volatile uint16_t epoch=0;
volatile uint8_t data_cnt=0;



#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif


void service_led_toggle(void);
void service_pin_toggle(void);
void send_service_message (char *message);

void SysTick_Handler(void)
{
	ms_counter++;
}

void TIM1_BRK_UP_TRG_COM_IRQHandler(void)
{
	service_pin_toggle();
	TIM1->SR &= ~(TIM_SR_UIF); // service pin - to see if TIM1 working
}

void TIM3_IRQHandler(void)
{
	char zprava[20];
	sprintf(zprava,"ms_counter: %ld\r\n",(long)ms_counter);
	send_service_message(zprava);
	service_led_toggle();
    TIM3->SR &= ~(TIM_SR_UIF); 				// service LED - to see if TIM3 working (send reports)
}


void main_clock_init(void)
{
	RCC->CR |= RCC_CR_HSEON_Msk;                // Select external crystal oscillator (48 MHz)
	while ((RCC->CR & RCC_CR_HSERDY_Msk)==0);   // Wait for external oscillator become ready

	RCC->CFGR &= ~RCC_CFGR_SW;				    // Reset switch to default
	RCC->CFGR |= RCC_CFGR_SW_0;                 // Switch system clock to HSE
	while ((RCC->CFGR & RCC_CFGR_SWS_HSE)==0);  // Wait for switch system clock to HSE
	SysTick_Config (48000000UL/1000U);			// 48MHz / 1000 -> 48000 ticks to interrupt
												// SysTick set to 1 ms
}

void ms_delay(uint32_t dwell)
{
	uint32_t from=ms_counter;
	while ((ms_counter-from)<dwell);
}

void adc_init(void)
{
	uint32_t autocal_value=0;
	char zprava[50];
	RCC->APBENR2 |= RCC_APBENR2_ADCEN;			// ADC clock enable
	ADC1->CR |= ADC_CR_ADVREGEN;
    ms_delay(5);								// !!! QDS (search for Tadcvreg_stup)
	ADC1->CR |= ADC_CR_ADCAL;					// Autocalibration
	while ((ADC1->CR & ADC_CR_ADCAL)!=0);		// Wait for finish autocalibration
	autocal_value=ADC1->DR;
	sprintf(zprava,"Autocal: 0x%lx\r\n",autocal_value);
	send_service_message(zprava);
	ADC1->CR |= ADC_CR_ADEN;
}

void adc_trigger_timer_init(void)
{
    RCC->APBENR2 |= RCC_APBENR2_TIM1EN;			// TIM1 clock enable
    TIM1->CR1 &= ~(TIM_CR1_CEN);				// Stop TIM1 before re-configuration
    TIM1->CR2 |= TIM_CR2_MMS2_1;				// TRGO2 for ADC enable (Update event -> ADC Trig.)
    TIM1->PSC = 4799U;							// 48 MHz / 4800 = 10 kHz
    TIM1->ARR = 99U;							// 10 kHz / 100 = 100 Hz
    TIM1->CNT = 0U;
    TIM1->DIER |= TIM_DIER_UIE;
    NVIC_EnableIRQ(TIM1_BRK_UP_TRG_COM_IRQn);   // Interrupt handler
    TIM1->CR1 |= TIM_CR1_CEN;
}


void stlink_com_timer_init(void)
{
	RCC->APBENR1 |= RCC_APBENR1_TIM3EN;
	TIM3->CR1 &= ~(TIM_CR1_CEN);
	TIM3->PSC=47999U;
	TIM3->ARR=999U;
	TIM3->CNT=0U;
	TIM3->DIER |= TIM_DIER_UIE;
	NVIC_EnableIRQ(TIM3_IRQn);
	TIM3->CR1 |= TIM_CR1_CEN;
}


void gpio_init(void)
{
    RCC->IOPENR|=(RCC_IOPENR_GPIOAEN | RCC_IOPENR_GPIOCEN);  // GPIO A+C clock enable
    GPIOA->MODER&=~(GPIO_MODER_MODE5);                       //
    GPIOA->MODER|=(GPIO_MODER_MODE5_0);                      // Service LED -> OUTPUT
    GPIOA->MODER&=~(GPIO_MODER_MODE6);
    GPIOA->MODER|=(GPIO_MODER_MODE6_0);
}

void service_usart_init(void)
{
	GPIOA->MODER &= ~(GPIO_MODER_MODE2);			// TX pin mode zeroing
	GPIOA->MODER |= GPIO_MODER_MODE2_1;				// TX pin set to alternate mode
	GPIOA->AFR[0] &= ~(0xFU << 8U);					// TX pin alternate function zeroing
	GPIOA->AFR[0] |= (0x01U << 8U);					// TX pin alternate function set
    RCC->APBENR1 |= RCC_APBENR1_USART2EN;
    USART2->BRR = 48000000UL/921600UL;
    USART2->CR1 |= (USART_CR1_UE|USART_CR1_TE|USART_CR1_RE);

}

void service_led_toggle(void)
{
	GPIOA->ODR^=GPIO_ODR_OD5;
}
void service_pin_toggle(void)
{
	GPIOA->ODR^=GPIO_ODR_OD6;
}

void send_service_message (char *message)
{
   uint8_t i=0;
   while (message[i]!='\0')
   {
     while ((USART2->ISR & USART_ISR_TXE_TXFNF)==0);
     USART2->TDR=message[i];
     i++;
   }

}

int main(void)
{
   main_clock_init();
   gpio_init();
   service_usart_init();
   stlink_com_timer_init();
   adc_init();
   adc_trigger_timer_init();



   while (1);
}
